//\n//  SplitViewController.swift\n//  EdenList\n//\n//  Custom UISplitViewController subclass configured for iOS 14+ with\n//  optimized layout for iPad and larger devices.\n//\n\nimport UIKit\n\nclass SplitViewController: UISplitViewController {\n    \noverride func viewDidLoad() {\n        super.viewDidLoad()    \n        \n        // Configure split view for iOS 14+\n        if #available(iOS 14.0, *) {\n            // Set display mode to side-by-side on iPad\n            preferredDisplayMode = .oneBesideSecondary\n            \n            // Configure primary column width\n            primaryBackgroundStyle = .sidebar\n            \n            // Set width constraints for primary column\n            if let primaryViewController = viewControllers.first {\n                let width: CGFloat = 350\n                primaryViewController.preferredContentSize = CGSize(width: width, height: -1)\n            }\n        }\n        \n        // Set the delegate\n        delegate = self\n    }\n}\n\n// MARK: - UISplitViewControllerDelegate\n\n@available(iOS 14.0, *)\nextension SplitViewController: UISplitViewControllerDelegate {\n    \n    func splitViewController(\n        _ svc: UISplitViewController,\n        topColumnForCollapsingPrimaryViewController primaryViewController: UIViewController\n    ) -> UISplitViewController.Column {\n        // When collapsing (rotating to portrait on iPad or resizing), keep primary visible\n        return .primary\n    }\n    \n    func splitViewController(\n        _ svc: UISplitViewController,\n        displayModeForExpandingPrimaryViewController primaryViewController: UIViewController\n    ) -> UISplitViewController.DisplayMode {\n        // Default display mode when expanded\n        return .oneBesideSecondary\n    }\n    \n    func splitViewController(\n        _ svc: UISplitViewController,\n        willChangeTo displayMode: UISplitViewController.DisplayMode\n    ) {\n        // Handle display mode changes if needed\n    }\n}